import java.util.List;

public class Pair {
    record Box<T>(T value) {                  // generic class (here a record)
        <R> Box<R> map(java.util.function.Function<? super T, ? extends R> f) {
            return new Box<>(f.apply(value)); // generic method with its own type parameter R
        }
    }

    static <T extends Comparable<T>> T max(List<T> items) {   // bounded type parameter
        T best = items.get(0);
        for (T t : items) {
            if (t.compareTo(best) > 0) best = t;
        }
        return best;
    }

    public static void main(String[] args) {
        Box<String> name = new Box<>("Dune");
        Box<Integer> len = name.map(String::length);
        System.out.println(name + " -> " + len);
        System.out.println(max(List.of(3, 9, 4)));
        System.out.println(max(List.of("pear", "apple", "zebra")));
        // max(List.of(new Object())); // does not compile: Object is not Comparable<Object>
    }
}

