public class Wild {
    static double sum(List<? extends Number> nums) {          // producer: we only read
        double s = 0;
        for (Number n : nums) s += n.doubleValue();
        return s;
    }

    static void fill(List<? super Integer> sink, int n) {     // consumer: we only write
        for (int i = 0; i < n; i++) sink.add(i);
    }

    static <T> void copy(List<? super T> dest, List<? extends T> src) {   // both, PECS
        for (T t : src) dest.add(t);
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(1, 2, 3);
        List<Double> dbls = List.of(1.5, 2.5);
        System.out.println(sum(ints) + " " + sum(dbls));
        List<Number> numbers = new ArrayList<>();
        List<Object> objects = new ArrayList<>();
        fill(numbers, 3);
        fill(objects, 2);
        copy(numbers, dbls);
        System.out.println(numbers + " " + objects);

        List<? extends Number> ro = ints;
        Number first = ro.get(0);          // reading is fine
        System.out.println(first);
        // ro.add(4);                      // compile error: capture of ? extends Number
        List<?> unknown = ints;
        Object o = unknown.get(1);
        System.out.println(o);
    }
}

