public class Erasure {
    static class Animal implements Comparable<Animal> {
        final int w;
        Animal(int w) { this.w = w; }
        public int compareTo(Animal o) { return Integer.compare(w, o.w); }
    }

    @SafeVarargs
    static <T> T[] bad(T... xs) { return xs; }

    static <T> T[] makeArray(T a, T b) { return bad(a, b); }

    @SuppressWarnings({"unchecked", "rawtypes"})
    public static void main(String[] args) throws Exception {
        List<String> a = new ArrayList<>();
        List<Integer> b = new ArrayList<>();
        System.out.println(a.getClass() == b.getClass());

        for (Method m : Animal.class.getDeclaredMethods()) {
            System.out.println(m + " bridge=" + m.isBridge());
        }

        List<String> strings = new ArrayList<>();
        List raw = strings;
        raw.add(42);                       // heap pollution: only an unchecked warning
        System.out.println("size " + strings.size());
        try {
            String s = strings.get(0);     // compiler inserted checkcast String here
            System.out.println(s);
        } catch (ClassCastException e) {
            System.out.println("CCE: " + e.getMessage().substring(0, 58) + "...");
        }

        try {
            String[] arr = makeArray("x", "y");
            System.out.println(arr.length);
        } catch (ClassCastException e) {
            System.out.println("CCE from varargs array: " + e.getMessage().substring(0, 60));
        }
        System.out.println(Arrays.toString(new List<?>[2]));
    }
}

