public class Shelf implements Iterable<String> {
    private final String[] books;
    Shelf(String... books) { this.books = books; }

    @Override public Iterator<String> iterator() {
        return new Iterator<>() {
            private int next = 0;
            @Override public boolean hasNext() { return next < books.length; }
            @Override public String next() {
                if (!hasNext()) throw new NoSuchElementException();
                return books[next++];
            }
        };
    }

    public static void main(String[] args) {
        for (String b : new Shelf("Dune", "Emma", "Ulysses")) System.out.println(b);

        Map<String, Integer> stock = new TreeMap<>(Map.of("Dune", 3, "Emma", 0, "Ulysses", 5));
        for (Map.Entry<String, Integer> e : stock.entrySet()) {
            System.out.println(e.getKey() + " -> " + e.getValue());
        }
        stock.values().removeIf(n -> n == 0);      // view: removes the entry from the map
        System.out.println(stock + " keys=" + stock.keySet());
    }
}

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class Cme {
    public static void main(String[] args) {
        List<String> books = new ArrayList<>(List.of("Dune", "Emma", "Ulysses", "Hamlet"));

        try {
            for (String b : books) {
                if (b.startsWith("E")) books.remove(b);   // structural change during iteration
            }
        } catch (java.util.ConcurrentModificationException e) {
            System.out.println("CME: " + e);
        }
        System.out.println(books);

        Iterator<String> it = books.iterator();
        while (it.hasNext()) {
            if (it.next().startsWith("E")) it.remove();   // the supported way
        }
        System.out.println(books);

        books.removeIf(b -> b.length() > 5);              // Java 8 shortcut
        System.out.println(books);
        List<String> two = new ArrayList<>(List.of("a", "b", "c"));
        for (String s : two) {
            if (s.equals("b")) two.remove(s);             // removing the second-to-last element
        }
        System.out.println(two);
    }
}

