import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

public class Growth {
    static int capacity(ArrayList<?> list) throws Exception {
        Field f = ArrayList.class.getDeclaredField("elementData");
        f.setAccessible(true);
        return ((Object[]) f.get(list)).length;
    }

    public static void main(String[] args) throws Exception {
        ArrayList<Integer> list = new ArrayList<>();
        System.out.println("new ArrayList(): capacity " + capacity(list));
        int last = capacity(list);
        for (int i = 1; i <= 100; i++) {
            list.add(i);
            int c = capacity(list);
            if (c != last) {
                System.out.println("after add #" + i + ": capacity " + last + " -> " + c);
                last = c;
            }
        }
        ArrayList<Integer> sized = new ArrayList<>(50);
        System.out.println("new ArrayList(50): capacity " + capacity(sized));
        List<Integer> copy = new ArrayList<>(List.of(1, 2, 3));
        System.out.println("copy of 3: capacity " + capacity((ArrayList<Integer>) copy));
        list.subList(10, 100).clear();
        list.trimToSize();
        System.out.println("after trimToSize: size " + list.size() + " capacity " + capacity(list));
    }
}

