public class Reality {
    static long time(Runnable r) {
        long t = System.nanoTime();
        r.run();
        return (System.nanoTime() - t) / 1_000_000;
    }

    public static void main(String[] args) {
        int n = 50_000;
        List<Integer> array = new ArrayList<>();
        List<Integer> linked = new LinkedList<>();
        for (int i = 0; i < n; i++) { array.add(i); linked.add(i); }

        for (int round = 0; round < 3; round++) {   // repeat so the JIT warms up
            long a = time(() -> { long s = 0; for (int i = 0; i < n; i++) s += array.get(i); });
            long l = time(() -> { long s = 0; for (int i = 0; i < n; i++) s += linked.get(i); });
            long af = time(() -> { List<Integer> x = new ArrayList<>();
                for (int i = 0; i < n; i++) x.add(0, i); });
            long lf = time(() -> { List<Integer> x = new LinkedList<>();
                for (int i = 0; i < n; i++) x.add(0, i); });
            System.out.println("get(i) loop: ArrayList " + a + " ms, LinkedList " + l + " ms | "
                + "add(0,x): ArrayList " + af + " ms, LinkedList " + lf + " ms");
        }
    }
}

