public class SetAlgebra {
    static <T> Set<T> union(Set<T> a, Set<T> b) {
        Set<T> r = new TreeSet<>(a);
        r.addAll(b);
        return r;
    }
    static <T> Set<T> intersection(Set<T> a, Set<T> b) {
        Set<T> r = new TreeSet<>(a);
        r.retainAll(b);
        return r;
    }
    static <T> Set<T> difference(Set<T> a, Set<T> b) {
        Set<T> r = new TreeSet<>(a);
        r.removeAll(b);
        return r;
    }
    public static void main(String[] args) {
        Set<Integer> a = Set.of(1, 2, 3, 4, 5);
        Set<Integer> b = Set.of(4, 5, 6, 7);
        System.out.println("union        = " + union(a, b));
        System.out.println("intersection = " + intersection(a, b));
        System.out.println("a minus b    = " + difference(a, b));
        Set<Integer> sym = union(a, b);
        sym.removeAll(intersection(a, b));
        System.out.println("symmetric    = " + sym);
        System.out.println("a contains all of intersection: " + a.containsAll(intersection(a, b)));
    }
}

