public class ConcurrentCounter {
    static void run(Map<String, Integer> map) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(4);
        for (int t = 0; t < 4; t++)
            pool.submit(() -> {
                for (int i = 0; i < 10_000; i++) map.merge("hits", 1, Integer::sum);
            });
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
    }
    public static void main(String[] args) throws Exception {
        Map<String, Integer> safe = new ConcurrentHashMap<>();
        run(safe);
        System.out.println("ConcurrentHashMap hits = " + safe.get("hits") + " (expected 40000)");
        try {
            new ConcurrentHashMap<String, Integer>().put("k", null);
        } catch (NullPointerException e) {
            System.out.println("null value rejected by ConcurrentHashMap");
        }
        Map<String, Integer> unsafe = new HashMap<>();
        run(unsafe);
        System.out.println("HashMap hits = " + unsafe.get("hits")
            + " (usually wrong; varies by run)");
    }
}

