    }
}

import java.lang.reflect.*;
import java.util.*;

public class BadHash {
    // Constant hash, NOT Comparable: worst case
    static final class BadKey {
        final int id;
        BadKey(int id) { this.id = id; }
        @Override public int hashCode() { return 42; }
        @Override public boolean equals(Object o) { return o instanceof BadKey b && b.id == id; }
    }
    // Constant hash but Comparable: tree bins can still binary-search
    static final class BadComparableKey implements Comparable<BadComparableKey> {
        final int id;
        BadComparableKey(int id) { this.id = id; }
        @Override public int hashCode() { return 42; }
        @Override public boolean equals(Object o) {
            return o instanceof BadComparableKey b && b.id == id;
        }
        @Override public int compareTo(BadComparableKey o) { return Integer.compare(id, o.id); }
    }
    static String describe(HashMap<?, ?> m) throws Exception {
        Field f = HashMap.class.getDeclaredField("table");
        f.setAccessible(true);
        Object[] t = (Object[]) f.get(m);
        for (Object n : t)
            if (n != null)
                return "table=" + t.length + ", the used bin holds a "
                    + n.getClass().getSimpleName();
        return "empty";
    }
    public static void main(String[] args) throws Exception {
        HashMap<BadComparableKey, Integer> m = new HashMap<>();
        for (int i = 1; i <= 12; i++) {
            m.put(new BadComparableKey(i), i);
            if (i == 1 || i >= 8) System.out.println("after " + i + " keys: " + describe(m));
        }
        int n = 20_000;
        for (int round = 0; round < 3; round++) {
            long t0 = System.nanoTime();
            HashMap<BadKey, Integer> a = new HashMap<>();
            for (int i = 0; i < n; i++) a.put(new BadKey(i), i);
            long t1 = System.nanoTime();
            HashMap<BadComparableKey, Integer> b = new HashMap<>();
            for (int i = 0; i < n; i++) b.put(new BadComparableKey(i), i);
            long t2 = System.nanoTime();
            HashMap<Integer, Integer> c = new HashMap<>();
            for (int i = 0; i < n; i++) c.put(i, i);
            long t3 = System.nanoTime();
            System.out.printf("round %d: non-Comparable %5d ms | Comparable %4d ms | good %3d ms%n",
                round, (t1 - t0) / 1_000_000, (t2 - t1) / 1_000_000, (t3 - t2) / 1_000_000);
        }
    }
}

