import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

public class LookupCost {
    public static void main(String[] args) {
        int n = 100_000;
        List<Integer> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            list.add(i);
        }
        Set<Integer> hash = new HashSet<>(list);
        Set<Integer> tree = new TreeSet<>(list);
        for (int round = 0; round < 3; round++) {
            System.out.println("round " + round
                + ": list " + time(list::contains) + " ms"
                + ", hash " + time(hash::contains) + " ms"
                + ", tree " + time(tree::contains) + " ms");
        }
    }

    static long time(java.util.function.Predicate<Integer> p) {
        long start = System.nanoTime();
        int hits = 0;
        for (int i = 0; i < 2_000; i++) {
            if (p.test(99_999 - i)) {
                hits++;
            }
        }
        if (hits != 2_000) {
            throw new AssertionError();
        }
        return (System.nanoTime() - start) / 1_000_000;
    }
}

import java.util.Arrays;

public class DynArray<E> {
    private Object[] items = new Object[4];
    private int size;

    public int size() {
        return size;
    }

    public void add(E e) {
        if (size == items.length) {
            items = Arrays.copyOf(items, items.length * 2);
        }
        items[size++] = e;
    }

    @SuppressWarnings("unchecked")
    public E get(int index) {
        checkIndex(index);
        return (E) items[index];
    }

    public E remove(int index) {
        checkIndex(index);
        E old = get(index);
        System.arraycopy(items, index + 1, items, index, size - index - 1);
        items[--size] = null;
        return old;
    }

    private void checkIndex(int index) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException("index " + index + ", size " + size);
        }
    }

    @Override
    public String toString() {
        return Arrays.toString(Arrays.copyOf(items, size));
    }

    public static void main(String[] args) {
        DynArray<String> a = new DynArray<>();
        for (String s : "ant bee cat dog eel fox".split(" ")) {
            a.add(s);
        }
        assert a.size() == 6;
        assert a.get(4).equals("eel");
        assert a.remove(1).equals("bee");
        assert a.size() == 5 && a.get(1).equals("cat");
        try {
            a.get(5);
            assert false : "should have thrown";
        } catch (IndexOutOfBoundsException expected) {
            System.out.println("caught: " + expected.getMessage());
        }
        System.out.println(a + " size=" + a.size());
        System.out.println("all DynArray checks passed");
    }
}

public class SinglyLinkedList<E> {
    private static class Node<E> {
        E value;
        Node<E> next;

        Node(E value) {
            this.value = value;
        }
    }

    private Node<E> head;
    private int size;

    public void addFirst(E e) {
        Node<E> n = new Node<>(e);
        n.next = head;
        head = n;
        size++;
    }

    public void addLast(E e) {
        Node<E> n = new Node<>(e);
        if (head == null) {
            head = n;
        } else {
            Node<E> cur = head;
            while (cur.next != null) {
                cur = cur.next;
            }
            cur.next = n;
        }
        size++;
    }

    public boolean remove(E e) {
        Node<E> prev = null;
        for (Node<E> cur = head; cur != null; prev = cur, cur = cur.next) {
            if (java.util.Objects.equals(cur.value, e)) {
                if (prev == null) {
                    head = cur.next;
                } else {
                    prev.next = cur.next;
                }
                size--;
                return true;
            }
        }
        return false;
    }

    public void reverse() {
        Node<E> prev = null;
        Node<E> cur = head;
        while (cur != null) {
            Node<E> next = cur.next;
            cur.next = prev;
            prev = cur;
            cur = next;
        }
        head = prev;
    }

    public int size() {
        return size;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("[");
        for (Node<E> cur = head; cur != null; cur = cur.next) {
            sb.append(cur.value);
            if (cur.next != null) {
                sb.append(" -> ");
            }
        }
        return sb.append("]").toString();
    }

    public static void main(String[] args) {
        SinglyLinkedList<Integer> list = new SinglyLinkedList<>();
        list.addLast(2);
        list.addLast(3);
        list.addFirst(1);
        System.out.println(list + " size=" + list.size());
        assert list.toString().equals("[1 -> 2 -> 3]");
        list.reverse();
        System.out.println("reversed: " + list);
        assert list.toString().equals("[3 -> 2 -> 1]");
        assert list.remove(2) && !list.remove(99);
        assert list.size() == 2;
        System.out.println("after remove(2): " + list);
    }
}

public class MyHashMap<K, V> {
    private static class Entry<K, V> {
        final K key;
        V value;
        Entry<K, V> next;

        Entry(K key, V value, Entry<K, V> next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    private Entry<K, V>[] table = newTable(16);
    private int size;

    @SuppressWarnings("unchecked")
    private static <K, V> Entry<K, V>[] newTable(int n) {
        return (Entry<K, V>[]) new Entry[n];
    }

    private static int hash(Object key) {
        int h = key == null ? 0 : key.hashCode();
        return h ^ (h >>> 16);
    }

    private static int indexFor(int hash, int length) {
        return hash & (length - 1);
    }

    public V get(K key) {
        for (Entry<K, V> e = table[indexFor(hash(key), table.length)]; e != null; e = e.next) {
            if (java.util.Objects.equals(e.key, key)) {
                return e.value;
            }
        }
        return null;
    }

    public V put(K key, V value) {
        int i = indexFor(hash(key), table.length);
        for (Entry<K, V> e = table[i]; e != null; e = e.next) {
            if (java.util.Objects.equals(e.key, key)) {
                V old = e.value;
                e.value = value;
                return old;
            }
        }
        table[i] = new Entry<>(key, value, table[i]);
        if (++size > table.length * 3 / 4) {
            resize();
        }
        return null;
    }

    private void resize() {
        Entry<K, V>[] old = table;
        table = newTable(old.length * 2);
        for (Entry<K, V> head : old) {
            for (Entry<K, V> e = head; e != null; ) {
                Entry<K, V> next = e.next;
                int i = indexFor(hash(e.key), table.length);
                e.next = table[i];
                table[i] = e;
                e = next;
            }
        }
    }
    public int size() {
        return size;
    }

    public int capacity() {
        return table.length;
    }

    public static void main(String[] args) {
        MyHashMap<String, Integer> m = new MyHashMap<>();
        m.put("one", 1);
        m.put("two", 2);
        m.put(null, 0);
        assert m.get("two") == 2;
        assert m.get(null) == 0;
        assert m.put("one", 11) == 1 && m.get("one") == 11;
        assert m.size() == 3;
        for (int i = 0; i < 1000; i++) {
            m.put("k" + i, i);
        }
        for (int i = 0; i < 1000; i++) {
            assert m.get("k" + i) == i;
        }
        assert m.get("missing") == null;
        System.out.println("size=" + m.size() + " capacity=" + m.capacity());
        System.out.println("all MyHashMap checks passed");
    }
}

import java.util.HashMap;
import java.util.Map;

public class LruCache<K, V> {
    private static class Node<K, V> {
        K key;
        V value;
        Node<K, V> prev;
        Node<K, V> next;
    }

    private final int capacity;
    private final Map<K, Node<K, V>> index = new HashMap<>();
    private final Node<K, V> head = new Node<>();
    private final Node<K, V> tail = new Node<>();

    public LruCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public V get(K key) {
        Node<K, V> n = index.get(key);
        if (n == null) {
            return null;
        }
        unlink(n);
        linkAfterHead(n);
        return n.value;
    }

    public void put(K key, V value) {
        Node<K, V> n = index.get(key);
        if (n != null) {
            n.value = value;
            unlink(n);
            linkAfterHead(n);
            return;
        }
        if (index.size() == capacity) {
            Node<K, V> lru = tail.prev;
            unlink(lru);
            index.remove(lru.key);
        }
        n = new Node<>();
        n.key = key;
        n.value = value;
        index.put(key, n);
        linkAfterHead(n);
    }

    private void unlink(Node<K, V> n) {
        n.prev.next = n.next;
        n.next.prev = n.prev;
    }

    private void linkAfterHead(Node<K, V> n) {
        n.next = head.next;
        n.prev = head;
        head.next.prev = n;
        head.next = n;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("[");
        for (Node<K, V> n = head.next; n != tail; n = n.next) {
            sb.append(n.key).append('=').append(n.value);
            if (n.next != tail) {
                sb.append(", ");
            }
        }
        return sb.append("] (most recent first)").toString();
    }
    public static void main(String[] args) {
        LruCache<String, Integer> c = new LruCache<>(2);
        c.put("a", 1);
        c.put("b", 2);
        c.get("a");
        c.put("c", 3);
        System.out.println(c);
        assert c.get("b") == null;
        assert c.get("a") == 1 && c.get("c") == 3;
        c.put("a", 10);
        c.put("d", 4);
        System.out.println(c);
        assert c.get("c") == null && c.get("a") == 10;
        System.out.println("all LruCache checks passed");
    }
}
